public handle(
  _layoutEngine: ILayoutEngine,
  previousDiagram: Diagram | null,
  node: Node<SysMLNoteNodeData, 'sysMLNoteNode'>,
  _: Node<NodeData, DiagramNodeType>[],
  _directChildren: Node<NodeData, DiagramNodeType>[],
  _newlyAddedNodes: Node<NodeData, DiagramNodeType>[],
  forceDimensions?: ForcedDimensions
) {
  const borderWidth = getNodeBorderWidth(node.data.style);

  const nodeMinComputeHeight = (node.data.insideLabel?.height ?? 0) + borderWidth * 2;

  const nodeWidth = forceDimensions?.width ?? node?.width ?? 200;
  const nodeHeight = forceDimensions?.height ?? getDefaultOrMinHeight(nodeMinComputeHeight, node);

  const previousNode = (previousDiagram?.nodes ?? []).find((previousNode) => previousNode.id === node.id);
  const previousDimensions = computePreviousSize(previousNode, node);

  if (node.data.resizedByUser && !forceDimensions?.width) {
    if (nodeWidth > previousDimensions.width) {
      node.width = nodeWidth;
    } else {
      node.width = previousDimensions.width;
    }
  } else {
    node.width = nodeWidth;
  }

  if (node.data.resizedByUser && !forceDimensions?.height) {
    if (nodeMinComputeHeight > previousDimensions.height) {
      node.height = nodeMinComputeHeight;
    } else {
      node.height = previousDimensions.height;
    }
  } else {
    node.height = nodeHeight;
  }

  if (node.data.nodeDescription?.keepAspectRatio) {
    applyRatioOnNewNodeSizeValue(node);
  }
}

export const computePreviousSize = (
  previousNode: Node<NodeData, DiagramNodeType> | undefined,
  node: Node<NodeData, DiagramNodeType>
): Dimensions => {
  let previousDimensions: Dimensions;
  const nodeDefaultHeight: number = node.data.defaultHeight ?? defaultHeight;
  const nodeDefaultWidth: number = node.data.defaultWidth ?? defaultWidth;

  if (node.data.isNew) {
    previousDimensions = {
      height: nodeDefaultHeight,
      width: nodeDefaultWidth,
    };
  } else if (previousNode) {
    previousDimensions = {
      height: previousNode.height ?? nodeDefaultHeight,
      width: previousNode.width ?? nodeDefaultWidth,
    };
  } else {
    previousDimensions = {
      height: node.height ?? nodeDefaultHeight,
      width: node.width ?? nodeDefaultWidth,
    };
  }

  return previousDimensions;
};

export const getDefaultOrMinHeight = (minHeight: number | undefined, node: Node<NodeData>): number => {
  return Math.max(minHeight ?? -Infinity, node.data.defaultHeight ?? defaultHeight);
};

export const applyRatioOnNewNodeSizeValue = (node: Node<NodeData>) => {
  const initRatio = (node.data.defaultWidth || defaultWidth) / (node.data.defaultHeight || defaultHeight);
  if (node.width && node.height) {
    const newRatio = node.width / node.height;
    if (initRatio > newRatio) {
      node.width = node.height * initRatio;
    }
    if (initRatio < newRatio) {
      node.height = node.width / initRatio;
    }
  }
};

export const getNodeBorderWidth = (style: CSSProperties): number => {
  const borderWidthStyle: string | number | undefined = style.borderLeftWidth ?? style.borderWidth;
  if (borderWidthStyle === undefined) {
    return 0;
  }

  const borderWidth: number =
    typeof borderWidthStyle === 'number' ? borderWidthStyle : Number.parseFloat(borderWidthStyle);
  return Number.isFinite(borderWidth) ? borderWidth : 0;
};
